@once
<style>
.fa-wett{color:var(--fa-ink);font-size:14px;min-width:0}.fa-wett *{box-sizing:border-box}.fa-wett p{margin:10px 0;line-height:1.6}.fa-wett h2{font-size:19px;font-weight:600}.fa-wett h3{font-size:18px;font-weight:600;margin:10px 0}.fa-wett small{font-size:12px;color:var(--fa-ink-3)}.fa-wett a{color:var(--fa-accent);text-decoration:underline}.fa-wett-toolbar,.fa-wett-actions{display:flex;flex-wrap:wrap;align-items:center;gap:12px;margin:14px 0}.fa-wett-toolbar p{flex:1}.fa-wett-panel{border:1px solid var(--fa-line);border-radius:12px;padding:20px;background:var(--fa-surface);margin:16px 0;min-width:0;overflow-wrap:anywhere}.fa-wett-form{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:18px;margin:18px 0}.fa-wett label{display:flex;flex-direction:column;gap:6px;min-width:0;font-size:13px}.fa-wett input:not([type=checkbox]),.fa-wett textarea,.fa-wett select{width:100%;min-width:0;min-height:44px;border:1px solid var(--fa-line);border-radius:8px;background:var(--fa-ground);color:var(--fa-ink);padding:10px;font:inherit}.fa-wett .fa-wett-check{display:flex;flex-direction:row;align-items:flex-start;gap:8px;margin:12px 0}.fa-wett-check input{margin-top:3px}.fa-wett-profile{display:grid;grid-template-columns:repeat(auto-fit,minmax(210px,1fr));gap:12px}.fa-wett-profil{display:flex;flex-direction:column;gap:6px;text-align:left;padding:16px;border:1px solid var(--fa-line);border-radius:10px;background:var(--fa-surface);color:var(--fa-ink);overflow-wrap:anywhere}.fa-wett-profil.is-active{border-color:var(--fa-accent);background:var(--fa-accent-soft)}.fa-wett .fa-btn{border:1px solid var(--fa-line);border-radius:8px;padding:8px 12px;min-height:44px;color:var(--fa-ink);background:var(--fa-surface);font-size:13px}.fa-wett-notice{padding:14px;background:var(--fa-ok-soft);border-radius:8px}.fa-wett button{cursor:pointer}.fa-wett button:disabled{opacity:.5;cursor:default}.fa-wett button:focus-visible,.fa-wett a:focus-visible{outline:3px solid var(--fa-accent);outline-offset:3px}@media(max-width:760px){.fa-wett-form{grid-template-columns:1fr}.fa-wett-panel{padding:16px}.fa-wett-profile{grid-template-columns:1fr}.fa-wett input,.fa-wett select,.fa-wett textarea{font-size:16px!important}}
</style>
@endonce
